#!/usr/bin/env node
// Evaluate the frozen predecessor without registry writes.
import fs from 'node:fs';import {execFileSync} from 'node:child_process';import {gunzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';
import {recognizeFiniteHeadBindings} from '../associativvordes/js/associative-family-v6-head-recognition.js';
const root='audit/associative-family-v6/oper-relat-continuation-20261004/',s=JSON.parse(fs.readFileSync(root+'decision.json')),hash=b=>createHash('sha256').update(b).digest('hex');
const old=p=>execFileSync('git',['show',s.source_head+':'+p],{maxBuffer:32*1024*1024}),bytes=old('associativvordes/family-index-v6/lexical-head-review.json.gz'),prior=JSON.parse(gunzipSync(bytes));
assert.equal(hash(bytes),s.predecessor_review_sha256);assert.equal(prior.version,s.predecessor_review_version);
const backlog=JSON.parse(gunzipSync(old('associativvordes/family-index-v6/generated/review-backlog.json.gz'))).flatMap(u=>u.source_records),records=[],facts=[],evidence=[],bindings=[];
for(const g of s.groups){const key=hash(g.language+'\0'+g.normalized_head+'\0'+g.sense).slice(0,24),fid='lexical-fact:'+key,eid='evidence:'+key;assert(!prior.lexical_facts.some(f=>f.id===fid));facts.push({id:fid,language:g.language,normalized_head:g.normalized_head,sense:g.sense,forms:g.forms,component_stems:g.component_stems,evidence_ids:[eid],version:1});evidence.push({id:eid,language:g.language,head:g.normalized_head,sense:g.sense,status:'accepted',evidence_kind:'lexical_identity',sources:g.sources,establishes_family_membership:false});
 for(const r of g.records){assert(backlog.some(x=>x.language===r.language&&x.lemma_id===r.lemma_id&&x.canonical_root===g.root&&x.word===r.word&&x.status===r.status));assert(!prior.finite_bindings.some(b=>b.language===r.language&&b.family_id==='family:'+g.root&&b.lemma_id===r.lemma_id));records.push({...r,family_id:'family:'+g.root});bindings.push({language:r.language,lemma_id:r.lemma_id,word:r.word,family_id:'family:'+g.root,fact_id:fid,identity_proof:[{path:s.source_queue,sha256:s.source_queue_sha256,lemma_id:r.lemma_id,word:r.word}],...(r.component_segmentation?{link_role:'reviewed_lexical_base_component',component_segmentation:r.component_segmentation}:{link_role:'whole_lexeme'})});}}
assert.equal(recognizeFiniteHeadBindings({records,facts,evidence,bindings}).recognized.length,6);
console.log(JSON.stringify({schema_version:6,verdict:'pass',mode:'finite_dry_run_against_frozen_predecessor',source_head:s.source_head,predecessor_review_version:s.predecessor_review_version,predecessor_review_sha256:s.predecessor_review_sha256,decision_sha256:hash(fs.readFileSync(root+'decision.json')),exact_new_links:records.map(r=>({language:r.language,family_id:r.family_id,lemma_id:r.lemma_id,word:r.word,status:'pending_to_accepted'})),new_heads:3,new_family_edge_decisions:3,withheld_records:26,production_enabled:false},null,2));
